# critique1 (8: компанія × гострота критики L0 нейтрально…L3 різко-емоційно, ті самі перевірені факти)
TEXT_SETS = {'srcpair2': _SRCPAIR2, 'ladder1': _LADDER1, 'brand1': _BRAND1, 'brand2': _BRAND2, 'brand3': _BRAND3, 'len1': _LEN1, 'duck1': _DUCK1, 'critique1': _CRITIQUE1}
TEXTS = _SRCPAIR2  # зворотна сумісність

WARMUP_TEXT = 'Тест. Розігрів сервісу перед експериментом.'

PAUSE_S = float(os.environ.get('EXPERIMENT_PAUSE', '2.0'))       # пауза між викликами oracle
RETRY_WAIT_S = float(os.environ.get('EXPERIMENT_RETRY_WAIT', '6.0'))
WARMUP_WAIT_S = float(os.environ.get('EXPERIMENT_WARMUP_WAIT', '20.0'))

# ── Python 3.13: concurrent.futures підвантажує ThreadPoolExecutor ЛІНИВО при першому
# зверненні, а /api/analyze його використовує. Якщо перше звернення трапляється у фоновому
# потоці бігуна, імпорт падає ("partially initialized module ... circular import").
# Тому підвантажуємо його тут, у головному потоці, при старті сервісу.
try:
    import concurrent.futures.thread  # noqa: F401
    from concurrent.futures import ThreadPoolExecutor as _TPE_PRELOAD  # noqa: F401
except Exception as _preload_err:  # не валимо старт сервісу
    print(f'[exp] попереднє завантаження concurrent.futures не вдалося: {_preload_err!r}')


def _preload_ok():
    try:
        import concurrent.futures as _cf
        _cf.ThreadPoolExecutor  # звернення запускає лінивий імпорт, якщо він ще не відбувся
        return True, ''
    except Exception as e:
        return False, repr(e)


bp = Blueprint('experiment_runner', __name__)
_lock = threading.Lock()
_state = {
    'running': False, 'stop': False, 'exp': None, 'set': None, 'rss': 'on', 'phase': '', 'runs': 0, 'total': 0, 'done': 0,
    'errors': 0, 'last_error': None, 'last_item': None, 'started': None, 'finished': None,
    'analysis_ok': 0, 'analysis_total': 0, 'skipped_analysis': [], 'per_variant': {},
}


def _plain(msg, code=200):
    return Response(msg, status=code, mimetype='text/plain; charset=utf-8')


def _authorized():
    tok = os.environ.get('EXPERIMENT_TOKEN', '')
    given = request.args.get('token', '') or request.headers.get('X-Experiment-Token', '')
    return bool(tok) and hmac.compare_digest(tok, given)


def _existing_counts(get_sb, exp):
    """Скільки oracle-рядків для цього experiment_id вже є в witness_log (для resume=1)."""
    try:
        sb = get_sb()
        try:
            rows = (sb.table('witness_log').select('variant,rss_mode')
                    .eq('experiment_id', exp).eq('endpoint', 'oracle').limit(5000).execute().data) or []
        except Exception:  # колонки rss_mode ще нема (міграція не виконана)
            rows = (sb.table('witness_log').select('variant')
                    .eq('experiment_id', exp).eq('endpoint', 'oracle').limit(5000).execute().data) or []
        counts = {}
        for r in rows:
            key = (r.get('variant'), r.get('rss_mode') or 'on')
            counts[key] = counts.get(key, 0) + 1
        return counts
    except Exception as e:
        print(f'[exp] resume: не вдалося прочитати witness_log: {e!r}')
        return {}


def _run(app_obj, exp, runs, texts, existing, rss='on'):
    client = app_obj.test_client()
    diags = {}
    try:
        # 0) розігрів: перший analyze після деплою повільний (холодний RSS-контекст),
        #    тому спершу чекаємо на успішну відповідь на короткий текст (до ~6 спроб).
        _state['phase'] = 'розігрів сервісу'
        for _attempt in range(6):
            if _state['stop']:
                break
            try:
                r = client.post('/api/analyze', json={'text': WARMUP_TEXT})
                if r.status_code == 200:
                    break
                _state['last_error'] = f"розігрів: HTTP {r.status_code} {r.get_data(as_text=True)[:200]}"
            except Exception as e:
                _state['last_error'] = f"розігрів: {e!r}"
            time.sleep(WARMUP_WAIT_S)
        _state['phase'] = 'аналіз текстів'
        # 1) аналіз — один раз на текст (детермінований шар, повтори не потрібні)
        for t in texts:
            if _state['stop']:
                break
            try:
                r = client.post('/api/analyze', json={'text': t['text']})
                body = r.get_json(silent=True)
                if r.status_code == 200 and isinstance(body, dict):
                    diags[t['id']] = body
                    _state['analysis_ok'] += 1
                else:
                    _state['skipped_analysis'].append(t['id'])
                    _state['last_error'] = f"analyze {t['id']}: HTTP {r.status_code} {r.get_data(as_text=True)[:300]}"
            except Exception as e:
                _state['skipped_analysis'].append(t['id'])
                _state['last_error'] = f"analyze {t['id']}: {e!r}"
            time.sleep(0.5)

        if not diags:
            _state['last_error'] = (_state['last_error'] or '') + ' | аналіз не пройшов жодного тексту, oracle не запускався'

        _state['phase'] = 'oracle'
        # 2) oracle — N кіл, у кожному колі всі тексти в новому випадковому порядку
        rng = random.Random(exp)
        modes_all = ['on', 'off'] if rss == 'both' else [rss]
        for rnd in range(runs):
            # у режимі both пари (текст, режим RSS) перемішуються разом: дрейф новин у часі
            # розподіляється порівну між режимами
            order = [(t, m) for t in texts if t['id'] in diags for m in modes_all
                     if existing.get((t['id'], m), 0) <= rnd]
            rng.shuffle(order)
            for t, mode in order:
                if _state['stop']:
                    break
                res = diags[t['id']]
                payload = {
                    'diagnostics': res,
                    'article_text': res.get('article_text') or t['text'],
                    'language': 'uk',
                    'experiment_id': exp,
                    'variant': t['id'],
                }
                for k in ('entropy_boosted', 'triggered_count', 'entropy_multiplier', 'interaction_combos'):
                    if k in res:
                        payload[k] = res[k]
                if mode == 'off':
                    payload['disable_rss'] = True  # оракул не робить RSS-матчинг
                ok = False
                for attempt in range(2):
                    try:
                        r = client.post('/api/oracle', json=payload)
                        if r.status_code == 200:
                            ok = True
                            break
                        _state['last_error'] = f"oracle {t['id']}: HTTP {r.status_code} {r.get_data(as_text=True)[:300]}"
                    except Exception as e:
                        _state['last_error'] = f"oracle {t['id']}: {e!r}"
                    time.sleep(RETRY_WAIT_S)
                _state['done'] += 1
                _state['last_item'] = t['id'] + ('' if rss == 'on' else f':{mode}')
                if ok:
                    _k = t['id'] if rss == 'on' else f"{t['id']}:{mode}"
                    _state['per_variant'][_k] = _state['per_variant'].get(_k, 0) + 1
                else:
                    _state['errors'] += 1
                time.sleep(PAUSE_S)
            if _state['stop']:
                break
    except Exception as e:
        _state['last_error'] = f'runner crashed: {e!r}'
    finally:
        _state['running'] = False
        _state['phase'] = 'завершено'
        _state['finished'] = time.time()


def _launch(set_name, runs, exp, only, resume, rss='on'):
    if rss not in ('on', 'off', 'both'):
        return _plain('rss має бути on, off або both', 400)
    texts_all = TEXT_SETS.get(set_name)
    if texts_all is None:
        return _plain('невідомий набір: ' + str(set_name) + ' (є: ' + ', '.join(TEXT_SETS) + ')', 400)
    texts = [t for t in texts_all if not only or t['id'].startswith(only)]
    if not texts:
        return _plain('only= не збігається з жодним текстом', 400)
    ok, why = _preload_ok()
    if not ok:
        return _plain('concurrent.futures недоступний у цьому процесі: ' + why + '\n'
                      'Перезапусти сервіс у Render (Manual Deploy -> Restart) і спробуй знову.', 500)
    with _lock:
        if _state['running']:
            return _plain('Вже працює. Дивись /api/exp/status або зупини /api/exp/stop', 409)
        existing = {}
        if resume:
            get_sb = current_app.config.get('EXP_GET_SB')
            existing = _existing_counts(get_sb, exp) if get_sb else {}
        _modes = ['on', 'off'] if rss == 'both' else [rss]
        todo = sum(max(0, runs - existing.get((t['id'], m), 0)) for t in texts for m in _modes)
        _state.update(running=True, stop=False, exp=exp, set=set_name, rss=rss, phase='старт', runs=runs, total=todo,
                      done=0, errors=0, last_error=None, last_item=None, started=time.time(), finished=None,
                      analysis_ok=0, analysis_total=len(texts), skipped_analysis=[], per_variant={})
    app_obj = current_app._get_current_object()
    threading.Thread(target=_run, args=(app_obj, exp, runs, texts, existing, rss), daemon=True).start()
    return _plain(f'Запущено: набір={set_name}, rss={rss}, exp={exp}, текстів={len(texts)}, повторів={runs}, викликів oracle≈{todo}.\n'
                  f'Прогрес: /api/exp/status?token=...  (відкривай періодично, щоб сервіс не заснув)')


@bp.route('/api/exp/start')
def exp_start():
    if not _authorized():
        return _plain('Not found', 404)
    try:
        runs = max(1, min(int(request.args.get('runs', '1')), 20))
    except ValueError:
        return _plain('runs має бути числом', 400)
    set_name = (request.args.get('set') or 'srcpair2').strip()
    rss = (request.args.get('rss') or 'on').strip()
    exp = (request.args.get('exp') or (set_name + ('' if rss == 'on' else '-rss' + rss) + '-' + time.strftime('%m%d-%H%M')))[:60]
    return _launch(set_name, runs, exp, (request.args.get('only') or '').strip(), request.args.get('resume') == '1', rss)


@bp.route('/api/exp/ladder')
def exp_ladder():
    """Кнопка без параметрів: набір ladder1, 10 повторів, ім'я ladder1-ММДД-ГГХХ (щоб не помилитися в URL).
    Для дозапуску після обриву: /api/exp/ladder?token=T&resume=1&exp=<те саме ім'я>."""
    if not _authorized():
        return _plain('Not found', 404)
    try:
        runs = max(1, min(int(request.args.get('runs', '10')), 20))
    except ValueError:
        return _plain('runs має бути числом', 400)
    rss = (request.args.get('rss') or 'on').strip()
    exp = (request.args.get('exp') or ('ladder1' + ('' if rss == 'on' else '-rss' + rss) + '-' + time.strftime('%m%d-%H%M')))[:60]
    return _launch('ladder1', runs, exp, (request.args.get('only') or '').strip(), request.args.get('resume') == '1', rss)


@bp.route('/api/exp/go/<set_name>')
def exp_go(set_name):
    """Кнопка для будь-якого набору: /api/exp/go/brand1?token=T  (10 повторів, ім'я <набір>-ММДД-ГГХХ).
    Дозапуск: додай &resume=1&exp=<те саме ім'я>."""
    if not _authorized():
        return _plain('Not found', 404)
    try:
        runs = max(1, min(int(request.args.get('runs', '10')), 20))
    except ValueError:
        return _plain('runs має бути числом', 400)
    rss = (request.args.get('rss') or 'on').strip()
    exp = (request.args.get('exp') or (set_name + ('' if rss == 'on' else '-rss' + rss) + '-' + time.strftime('%m%d-%H%M')))[:60]
    return _launch(set_name, runs, exp, (request.args.get('only') or '').strip(), request.args.get('resume') == '1', rss)


@bp.route('/api/exp/status')
def exp_status():
    if not _authorized():
        return _plain('Not found', 404)
    s = _state
    now = time.time()
    lines = []
    lines.append(('ПРАЦЮЄ' if s['running'] else 'НЕ ПРАЦЮЄ') + f" | exp={s['exp']} | набір={s['set']} | rss={s['rss']} | фаза: {s['phase']}")
    lines.append(f"аналіз: {s['analysis_ok']}/{s['analysis_total']} ok"
                 + (f", пропущено: {', '.join(s['skipped_analysis'])}" if s['skipped_analysis'] else ''))
    lines.append(f"oracle: {s['done']}/{s['total']} зроблено, помилок: {s['errors']}")
    if s['started'] and s['done'] and s['running']:
        per = (now - s['started']) / max(1, s['done'])
        lines.append(f"орієнтовно лишилось: {int((s['total'] - s['done']) * per / 60)} хв")
    if s['last_item']:
        lines.append(f"останній текст: {s['last_item']}")
    if s['last_error']:
        lines.append(f"остання помилка: {s['last_error']}")
    if s['per_variant']:
        lines.append('успішних за варіантами: ' + ', '.join(f'{k}={v}' for k, v in sorted(s['per_variant'].items())))
    return _plain('\n'.join(lines))


@bp.route('/api/exp/stop')
def exp_stop():
    if not _authorized():
        return _plain('Not found', 404)
    _state['stop'] = True
    return _plain('Стоп запрошено: завершиться після поточного виклику.')


def register_experiment_runner(app, get_sb=None):
    """Підключення: register_experiment_runner(app, _get_sb) — один раз, після створення app."""
    app.config['EXP_GET_SB'] = get_sb
    app.register_blueprint(bp)
